using UnityEngine;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;public static class StateEF{public static string Main(){var l=Object.FindFirstObjectByType<ElevatorLesson>();var m=Object.FindFirstObjectByType<ElevatorPlayerMovement>();var map=l.presentation.space.sportsCentre;return Newtonsoft.Json.JsonConvert.SerializeObject(new{feet=m.FeetPosition.ToString("F5"),step=l.Flow.Step.ToString(),elapsed=l.Flow.Elapsed,framing=map.IsFraming,progress=map.ReframeProgress,canMove=m.CanMove,blocking=l.CinematicBlocking,overlay=map.space.overlay.Amount});}}